import { QuitRequestedError } from "../errors/QuitRequestedError.js";

const QUIT_KEY = "q";

// Helper function to capture a single keypress without pressing Enter, generated by AI.
export async function getSingleKey(promptText) {
  process.stdout.write(promptText);
  return new Promise((resolve, reject) => {
    const wasRaw = process.stdin.isRaw;
    process.stdin.setRawMode(true);
    process.stdin.resume();
    process.stdin.once("data", (data) => {
      process.stdin.setRawMode(wasRaw);
      const key = data.toString("utf8");
      process.stdout.write(key + "\n"); // Echo the pressed key so it displays nicely
      if (key.trim().toLowerCase() === QUIT_KEY) {
        reject(new QuitRequestedError(QUIT_KEY));
        return;
      }
      resolve(key);
    });
  });
}
